sys_script_include.script:
var DirectoryGroupAJAX = Class.create();
DirectoryGroupAJAX.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getUserGroups: function() {
        const userKey = this.getParameter("sysparm_user_key");
        const query = this.getParameter("sysparm_query");
        const pageToken = this.getParameter("sysparm_page_token");
        const maxResults = this.getParameter("sysparm_max_results");

        const api = new x_neyu_google_nyu.DirectoryGroupAPI();
        const response = api.getUserGroups({
            userKey: userKey,
            query: query,
            pageToken: pageToken,
            maxResults: maxResults
        });
        if (!response.error && response.status == 200) {
            const {
                responseBody,
                status
            } = response;
            return JSON.stringify({
                error: false,
                errorMessage: "",
                result: JSON.parse(responseBody),
                status: status
            });
        } else {
            const {
                status,
                errorMessage
            } = response;
            return {
                error: true,
                status: status,
                errorMessage: errorMessage,
                result: null
            };
        }
    },

    type: 'DirectoryGroupAJAX'
});
